<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Http\Resources\ReviewResource; use App\Models\Restaurant; use App\Models\Review; use Illuminate\Http\Request; use Illuminate\Database\QueryException;
class ReviewController extends Controller { public function index(Restaurant $restaurant) { return ReviewResource::collection($restaurant->reviews()->where('status','PUBLISHED')->with(['user','media'])->latest()->paginate(12)); } public function store(Request $request,Restaurant $restaurant) { $data=$request->validate(['rating'=>['required','integer','between:1,5'],'content'=>['nullable','string','max:5000']]); if(Review::where('restaurant_id',$restaurant->id)->where('user_id',$request->user()->id)->exists()) return response()->json(['message'=>'You have already reviewed this restaurant.'],409); $review=Review::create([...$data,'restaurant_id'=>$restaurant->id,'user_id'=>$request->user()->id]); return (new ReviewResource($review->load('user')))->response()->setStatusCode(201); } public function update(Request $request,Review $review) { abort_unless($review->user_id===$request->user()->id,403); $review->update($request->validate(['rating'=>['sometimes','integer','between:1,5'],'content'=>['sometimes','nullable','string','max:5000']])); return new ReviewResource($review->load('user')); } public function destroy(Request $request,Review $review) { abort_unless($review->user_id===$request->user()->id,403); $review->delete(); return response()->noContent(); } }
